  background: linear-gradient(135deg, #e94560, #0f3460);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #fff;
  box-shadow: 0 4px 15px rgba(233,69,96,0.4);
}
.custom-brand .brand-text {
  font-size: 1.2rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
}

/* ── User panel ── */
.user-panel-custom {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 16px;
  margin: 12px 12px 4px;
  background: rgba(255,255,255,0.06);
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.08);
}
.avatar-ring {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  padding: 2px;
  background: linear-gradient(135deg, #e94560, #a855f7);
  flex-shrink: 0;
}
.avatar-ring img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid #1a1a2e;
}
.user-info {
  display: flex;
  flex-direction: column;
}
.user-name {
  color: #fff;
  font-weight: 600;
  font-size: 0.95rem;
}
.user-status {
  color: #4ade80;
  font-size: 0.72rem;
  margin-top: 2px;
}
.user-status i {
  font-size: 0.55rem;
  vertical-align: middle;
}

/* ── Section headers ── */
.custom-header {
  padding: 18px 16px 6px !important;
  color: rgba(255,255,255,0.35) !important;
  font-size: 0.65rem !important;
  letter-spacing: 2px !important;
  font-weight: 700 !important;
}
.custom-header span {
  position: relative;
  padding-left: 10px;
}
.custom-header span::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 10px;
  background: #e94560;
  border-radius: 2px;
}

/* ── Nav links ── */
.custom-nav {
  padding: 0 8px 16px;
}
.custom-link {
  display: flex !important;
  align-items: center;
  gap: 12px;
  padding: 10px 14px !important;
  margin-bottom: 3px;
  border-radius: 10px !important;
  color: rgba(255,255,255,0.65) !important;
  transition: all 0.2s ease !important;
  border: 1px solid transparent;
}
.custom-link:hover {
  background: rgba(255,255,255,0.08) !important;
  color: #fff !important;
  border-color: rgba(255,255,255,0.1);
  transform: translateX(3px);
}
.custom-link.active {
  background: linear-gradient(135deg, #e94560, #c2185b) !important;
  color: #fff !important;
  box-shadow: 0 4px 15px rgba(233,69,96,0.35);
  border-color: transparent;
}
.custom-link.active .link-icon {
  background: rgba(255,255,255,0.2);
}

/* ── Link icon badge ── */
.link-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(255,255,255,0.07);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  flex-shrink: 0;
  transition: background 0.2s;
}
.custom-link p {
  margin: 0 !important;
  font-size: 0.875rem;
  font-weight: 500;
}

