/* ═══════════════════════════════════════════════
   GLOBAL INVENTORY SYSTEM STYLES
   Covers: page wrapper, tables, search, buttons,
           modals/forms, pagination, action icons
═══════════════════════════════════════════════ */

/* ── Page wrapper ── */
.px-3.py-3 {
  background: #f4f6fb;
  min-height: 100%;
}

/* ── Page title ── */
.card-title {
  font-size: 1.3rem;
  font-weight: 700;
  color: #1a1a2e;
  letter-spacing: 0.3px;
}

/* ── "Create New" button ── */
.btn-primary {
  background: linear-gradient(135deg, #e94560, #c2185b) !important;
  border: none !important;
  border-radius: 8px !important;
  font-weight: 600 !important;
  letter-spacing: 0.3px;
  box-shadow: 0 4px 12px rgba(233,69,96,0.3) !important;
  transition: transform 0.15s, box-shadow 0.15s !important;
}
.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(233,69,96,0.4) !important;
}

/* ── Search input ── */
.form-control {
  border-radius: 8px !important;
  border: 1.5px solid #e2e8f0 !important;
  padding: 10px 14px !important;
  font-size: 0.875rem !important;
  transition: border-color 0.2s, box-shadow 0.2s !important;
  background: #fff !important;
}
.form-control:focus {
  border-color: #e94560 !important;
  box-shadow: 0 0 0 3px rgba(233,69,96,0.12) !important;
  outline: none !important;
}

/* ── Select / dropdown ── */
.form-select {
  border-radius: 8px !important;
  border: 1.5px solid #e2e8f0 !important;
  padding: 10px 14px !important;
  font-size: 0.875rem !important;
  transition: border-color 0.2s, box-shadow 0.2s !important;
}
.form-select:focus {
  border-color: #e94560 !important;
  box-shadow: 0 0 0 3px rgba(233,69,96,0.12) !important;
}

/* ── Table wrapper ── */
.table-responsive {
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 16px rgba(0,0,0,0.07);
}

/* ── Table ── */
.table {
  margin-bottom: 0 !important;
  background: #fff;
}
.table thead tr {
  background: linear-gradient(135deg, #1a1a2e, #0f3460) !important;
}
.table thead th {
  color: #fff !important;
  font-weight: 600 !important;
  font-size: 0.8rem !important;
  letter-spacing: 0.6px !important;
  text-transform: uppercase !important;
  border: none !important;
  padding: 14px 12px !important;
}
.table tbody tr {
  transition: background 0.15s;
  border-bottom: 1px solid #f1f5f9 !important;
}
.table tbody tr:hover {
  background: #fef2f4 !important;
}
.table tbody td {
  vertical-align: middle !important;
  font-size: 0.875rem !important;
  color: #374151 !important;
  padding: 11px 12px !important;
  border: none !important;
}
.table-striped tbody tr:nth-of-type(odd) {
  background: #fafbff !important;
}
.table-striped tbody tr:nth-of-type(odd):hover {
  background: #fef2f4 !important;
}

/* ── Action icon buttons ── */
.btn-group .btn {
  padding: 5px 8px !important;
  border-radius: 7px !important;
  transition: transform 0.15s, background 0.15s !important;
}
.btn-group .btn:hover {
  background: #f1f5f9 !important;
  transform: scale(1.15);
}

/* ── Pagination ── */
.pagination {
  gap: 3px;
  margin-top: 12px !important;
}
.page-link {
  border-radius: 7px !important;
  border: 1.5px solid #e2e8f0 !important;
  color: #1a1a2e !important;
  font-size: 0.8rem !important;
  padding: 5px 11px !important;
  transition: all 0.15s !important;
}
.page-link:hover {
  background: #fef2f4 !important;
  border-color: #e94560 !important;
  color: #e94560 !important;
}
.page-item.active .page-link {
  background: linear-gradient(135deg, #e94560, #c2185b) !important;
  border-color: transparent !important;
  color: #fff !important;
  box-shadow: 0 3px 10px rgba(233,69,96,0.35) !important;
}
.page-item.disabled .page-link {
  opacity: 0.4 !important;
  pointer-events: none;
}

/* ── Modal ── */
.modal-content {
  border: none !important;
  border-radius: 16px !important;
  box-shadow: 0 20px 60px rgba(0,0,0,0.18) !important;
  overflow: hidden;
}
.modal-header {
  background: linear-gradient(135deg, #1a1a2e, #0f3460) !important;
  border-bottom: none !important;
  padding: 18px 24px !important;
}
.modal-title {
  color: #fff !important;
  font-weight: 700 !important;
  font-size: 1rem !important;
}
.modal-header .close {
  color: rgba(255,255,255,0.7) !important;
  opacity: 1 !important;
  text-shadow: none !important;
}
.modal-header .close:hover {
  color: #fff !important;
}
.modal-body {
  padding: 24px !important;
  background: #fff;
}
.modal-footer {
  background: #f8fafc !important;
  border-top: 1px solid #f1f5f9 !important;
  padding: 14px 24px !important;
}

/* ── Form labels ── */
.form-label {
  font-weight: 600 !important;
  font-size: 0.8rem !important;
  color: #374151 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.4px !important;
  margin-bottom: 5px !important;
}

/* ── Modal footer buttons ── */
.btn-secondary {
  background: #f1f5f9 !important;
  border: none !important;
  color: #374151 !important;
  border-radius: 8px !important;
  font-weight: 600 !important;
}
.btn-secondary:hover {
  background: #e2e8f0 !important;
  color: #1a1a2e !important;
}
.btn-success {
  background: linear-gradient(135deg, #10b981, #059669) !important;
  border: none !important;
  border-radius: 8px !important;
  font-weight: 600 !important;
  box-shadow: 0 4px 12px rgba(16,185,129,0.3) !important;
}
.btn-warning {
  background: linear-gradient(135deg, #f59e0b, #d97706) !important;
  border: none !important;
  border-radius: 8px !important;
  font-weight: 600 !important;
  color: #fff !important;
  box-shadow: 0 4px 12px rgba(245,158,11,0.3) !important;
}

